def split(sig):
    depth=0
    for i,ch in enumerate(sig):
        if ch in \"([{\": depth+=1
        elif ch in \")]}\": depth=max(0,depth-1)
        elif ch==\":\" and depth==0: return sig[:i],sig[i+1:]
    return sig,\"\"

def snapshot(commit, project):
    prefix=f\"MainProjects/{project}/AlgebraicJacobian\"
    raw=subprocess.check_output([HG,\"archive\",\"--format=tar\",commit,prefix],cwd=ROOT)
    out={}; files=0; strict=0
    with tarfile.open(fileobj=io.BytesIO(raw),mode=\"r:\") as tf:
      for m in tf:
        if not m.isfile() or not m.name.endswith(\".lean\"): continue
        files+=1
        text=tf.extractfile(m).read().decode(\"utf-8\")
        strict += text.count(\"(rep :\")
        for d in extract_declarations(text,library=project,file=m.name):
          a,b=split(d.signature)
          out[(m.name,d.name)]={\"file\":m.name,\"name\":d.name,\"line\":d.line,\"sig\":d.signature,
            \"input_occ\":a.count(\".RepresentableBy\"),\"result_occ\":b.count(\".RepresentableBy\")}
    consumers={k:v for k,v in out.items() if v[\"input_occ\"]}
    results={k:v for k,v in out.items() if v[\"result_occ\"]}
    producers={k:v for k,v in results.items() if not v[\"input_occ\"]}
    return {\"commit\":commit,\"project\":project,\"files\":files,\"strict\":strict,\"decls\":out,
      \"input_occ\":sum(v[\"input_occ\"] for v in out.values()),\"consumers\":consumers,
      \"results\":results,\"producers\":producers}

print(\"FROZEN_HEAD\",HEAD)
for project in [\"Algebraic-Jacobian-Challenge\",\"Algebraic-Jacobian-Challenge-Rebuild\"]:
  b=snapshot(BASE,project); h=snapshot(HEAD,project)
  def row(x): return {\"files\":x[\"files\"],\"strict\":x[\"strict\"],\"input_occ\":x[\"input_occ\"],\"consumer_decls\":len(x[\"consumers\"]),\"result_decls\":len(x[\"results\"]),\"direct_producers\":len(x[\"producers\"])}
  print(\"PROJECT\",project)
  print(\"BASE\",json.dumps(row(b),sort_keys=True))
  print(\"HEAD\",json.dumps(row(h),sort_keys=True))
  print(\"DELTA\",json.dumps({k:row(h)[k]-row(b)[k] for k in row(b)},sort_keys=True))
  newc={k:v for k,v in h[\"consumers\"].items() if k not in b[\"consumers\"]}
  gonec={k:v for k,v in b[\"consumers\"].items() if k not in h[\"consumers\"]}
  newp={k:v for k,v in h[\"producers\"].items() if k not in b[\"producers\"]}
  gonep={k:v for k,v in b[\"producers\"].items() if k not in h[\"producers\"]}
  print(\"NEW_CONSUMERS_BY_FILE\")
  for f,n in sorted(Counter(v[\"file\"] for v in newc.values()).items()): print(n,f)
  print(\"REMOVED_CONSUMERS\",len(gonec))
  print(\"NEW_DIRECT_PRODUCERS\",len(newp))
  for v in newp.values(): print(v[\"name\"],v[\"file\"],v[\"line\"])
  print(\"REMOVED_DIRECT_PRODUCERS\",len(gonep))
  print(\"HEAD_DIRECT_PRODUCERS\")
  for v in h[\"producers\"].values(): print(v[\"name\"],v[\"file\"],v[\"line\"])
PY"

